/**
 * Last non-empty lines of `output`, oldest first.
 * @param output The command output (terminal escapes already removed).
 * @param max How many lines to keep at most.
 * @returns Up to `max` trimmed lines, each cut to 300 characters.
 */
export function outputTail(output: string, max = 5): string[] {
  const lines = output
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean);
  return lines.slice(-max).map((l) => l.slice(0, 300));
}
